"""Replays the recorded {token} session against the frame decoder's bulk limit."""
import sys

BULK_LIMIT = 4096
FIXTURE_FRAMES = 412


class {Alt}Error(Exception):
    """A replayed frame declares a bulk length above the decoder limit."""


def replay():
    print("replaying {token} fixture (%d frames)" % FIXTURE_FRAMES)
    for frame in range(1, FIXTURE_FRAMES + 1):
        declared = {value} if frame == 318 else 64
        if declared > BULK_LIMIT:
            raise {Alt}Error(
                "frame %d declares a bulk length of %d bytes, above the decoder limit"
                % (frame, declared)
            )


if __name__ == "__main__":
    try:
        replay()
    except {Alt}Error as e:
        print("error: {Alt}Error: %s" % e, file=sys.stderr)
        sys.exit(1)

