#!/usr/bin/env python3
"""Replays recorded request paths from the {token} capture against the route table."""
import sys

CAPTURED = 240
ROUTES = ["/articles/:id", "/articles/search", "/users/:id/posts"]


class {Alt}Error(Exception):
    """A captured path that reached the service matches no registered route."""


def match(path):
    parts = path.strip("/").split("/")
    for route in ROUTES:
        want = route.strip("/").split("/")
        if len(want) == len(parts) and all(w.startswith(":") or w == p for w, p in zip(want, parts)):
            return route
    return None


def replay():
    print("replaying %d captured paths from {token}" % CAPTURED)
    for n in range(1, CAPTURED + 1):
        path = "/articles/%d/comments" % {value} if n == 177 else "/users/%d/posts" % n
        if match(path) is None:
            raise {Alt}Error("captured request %d (%s) matches no route" % (n, path))


if __name__ == "__main__":
    try:
        replay()
    except {Alt}Error as e:
        print("error: {Alt}Error: %s" % e, file=sys.stderr)
        sys.exit(1)
